package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import java.util.regex.*;
/** A selected original digit retains its identity while its place unit changes. */
public final class DecimalPowerPlaceRelations {
 private DecimalPowerPlaceRelations(){}
 public record Givens(DecimalPlaceRelations.Givens digit,int power,boolean multiply,BigDecimal afterUnit,BigDecimal afterValue,BigDecimal result){}
 public static Givens read(Question q){if(q==null||!DecimalPowerTen.supports(q.skillId)||q.prompt==null)return null;Matcher m=Pattern.compile("(\\d{1,2}\\.\\d{1,3}) ([×÷]) (10|100|1000)\\n(십의 자리|일의 자리|소수 첫째 자리|소수 둘째 자리|소수 셋째 자리) 숫자의 원래 값과 계산 후 값을 쓰세요\\.").matcher(q.prompt);if(!m.matches()||!m.group(2).equals(DecimalPowerTen.MUL.equals(q.skillId)?"×":"÷"))return null;var d=DecimalPlaceRelations.read(new Question(DecimalPlaceRelations.ID,m.group(1)+"의 "+m.group(4)+" 숫자와 그 숫자가 나타내는 값을 쓰세요.","","poison","poison"));if(d==null)return null;int power=Integer.parseInt(m.group(3));boolean multiply=DecimalPowerTen.MUL.equals(q.skillId);BigDecimal factor=BigDecimal.valueOf(power),after=multiply?d.unit().multiply(factor):d.unit().divide(factor),value=new BigDecimal(d.raw()),result=multiply?value.multiply(factor):value.divide(factor);return new Givens(d,power,multiply,after,after.multiply(BigDecimal.valueOf(d.digit())),result);}
 static Question make(String id,String raw,int power,int position){Question q=new Question(id,raw+(DecimalPowerTen.MUL.equals(id)?" × ":" ÷ ")+power+"\n"+DecimalPlaceRelations.place(position)+" 숫자의 원래 값과 계산 후 값을 쓰세요.","","","","");Givens v=read(q);if(v==null)throw new IllegalArgumentException("Power/place givens");q.answers=new String[]{text(v.result),text(v.digit.value()),text(v.afterValue)};q.labels=new String[]{"계산 결과","원래 숫자의 값","계산 후 숫자의 값"};q.decimal=true;q.answerFormat="decimalValue";q.stepSupport=false;attach(q);return q;}
 static Checker.Result check(Question q,List<String> answers){Givens v=read(q);if(v==null||answers==null||answers.size()!=3)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"세 값 입력 필요");BigDecimal[] values={v.result,v.digit.value(),v.afterValue};for(int i=0;i<3;i++){String raw=answers.get(i)==null?"":Expression.normalize(answers.get(i).trim());if(raw.length()>120||!raw.matches("[+-]?\\d+(?:\\.\\d+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,i,"수로 입력 필요");if(new BigDecimal(raw).compareTo(values[i])!=0)return new Checker.Result(Checker.Status.WRONG_ANSWER,i,"이 값 확인");}return new Checker.Result(Checker.Status.CORRECT,-1,"계산 확인 완료");}
 public static void attach(Question q){Givens v=read(q);if(v==null)return;int moves=Integer.toString(v.power).length()-1;StudyGuide h=new StudyGuide().transfer(false);h.teachingVersion="decimal-power-place-v1";step(h,"원래 수를 쓰세요.","원래 수 = ",v.digit.raw(),true);step(h,"곱하거나 나누는 수를 쓰세요.","곱하거나 나누는 수 = ",""+v.power,false);step(h,"숫자의 자리가 움직이는 칸 수를 쓰세요.","움직이는 칸 수 = ",""+moves,false);h.choice("숫자의 자리가 움직이는 방향을 고르세요.",Map.of("left","왼쪽","right","오른쪽"),v.multiply?"left":"right");step(h,"문제에서 지정한 자리의 숫자를 쓰세요.","선택한 자리 숫자 = ",""+v.digit.digit(),false);step(h,"원래 자리의 한 단위 값을 쓰세요.","원래 자리의 단위 = ",text(v.digit.unit()),true);step(h,"숫자에 원래 자리의 단위를 곱하세요.","원래 숫자의 값 = ",text(v.digit.value()),true);step(h,v.multiply?"원래 자리의 단위에 곱하는 수를 곱하세요.":"원래 자리의 단위를 나누는 수로 나누세요.","계산 후 자리의 단위 = ",text(v.afterUnit),true);step(h,"같은 숫자에 계산 후 자리의 단위를 곱하세요.","계산 후 숫자의 값 = ",text(v.afterValue),true);step(h,"원래 수의 전체 계산 결과를 쓰세요.","계산 결과 = ",text(v.result),true);q.studyGuide=h;}
 private static String text(BigDecimal value){return value.stripTrailingZeros().toPlainString();}
 private static void step(StudyGuide h,String instruction,String before,String expected,boolean decimal){h.step(instruction,before,"",expected);if(decimal)h.frames.get(h.frames.size()-1).inputFormat="decimalValue";}
}
